import re
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()



def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


def show(value: Any) -> str:
    text = od_text(value)
    return text.rstrip("0").rstrip(".") if re.fullmatch(r"-?\d+\.\d+", text) else text


order_id = params["order_id"]
reason = od_text(params.get("reason")) or "other"
if reason not in ("misread", "wrong_product", "wrong_conversion", "customer_rule", "missing_mapping", "wrong_customer", "duplicate", "customer_changed", "other"):
    reason = "other"
reason_note = od_text(params.get("reason_note"))
corrected_by = od_text(params.get("corrected_by"))
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
order_number = od_text(order.get("title"))
account_code = od_text(od_data(order).get("account_code"))
proposed: dict[str, dict[str, Any]] = {}
for item in (params.get("proposed_lines") or []):
    if isinstance(item, dict) and item.get("line_id"):
        proposed[od_text(item.get("line_id"))] = dict(item)
catalogue = [r for r in od_rows("od_customer_catalogue", account_code) if od_text(od_data(r).get("account_code")) == account_code] if account_code else []
corrections = 0
learned_count = 0
seen: list[str] = []
for row in (od_order_lines(order_id, order_number) if proposed else []):
    line_id = od_text(row.get("id"))
    seen.append(line_id)
    d = od_data(row)
    before = proposed.get(line_id)
    label = od_text(row.get("title"))
    changes: list[tuple[str, str, str]] = []
    if before is None:
        changes.append(("line_added", "", show(d.get("quantity")) + " " + od_text(d.get("unit")) + " " + od_text(d.get("item_code"))))
    else:
        if od_text(before.get("item_code")) != od_text(d.get("item_code")):
            changes.append(("product", od_text(before.get("item_code")), od_text(d.get("item_code"))))
        if abs(as_number(before.get("quantity")) - as_number(d.get("quantity"))) > 0.0005:
            changes.append(("quantity", show(before.get("quantity")), show(d.get("quantity"))))
        if od_text(before.get("unit")) != od_text(d.get("unit")):
            changes.append(("unit", od_text(before.get("unit")), od_text(d.get("unit"))))
    if not changes:
        continue
    learned = False
    customer_code = od_text(d.get("customer_code"))
    item_code = od_text(d.get("item_code"))
    if account_code and item_code and any(c[0] == "product" for c in changes) and (customer_code or od_text(d.get("raw_text"))):
        description = od_text(d.get("raw_text"))
        if customer_code:
            description = description.replace(customer_code, " ")
        description = re.sub(r"(?i)\b(x|\d+(\.\d+)?|" + re.escape(od_text(d.get("raw_unit"))) + r")\b" if od_text(d.get("raw_unit")) else r"(?i)\b(x|\d+(\.\d+)?)\b", " ", description)
        description = re.sub(r"\s+", " ", description).strip()[:300]
        known = [r for r in catalogue if (customer_code and od_text(od_data(r).get("customer_code")).upper() == customer_code.upper()) or (not customer_code and od_norm(od_data(r).get("customer_description")) == od_norm(description))]
        mapping: dict[str, Any] = {"account_code": account_code, "customer_code": customer_code[:120], "customer_description": description, "customer_unit": od_text(d.get("raw_unit"))[:40], "item_code": item_code, "conversion_factor": 1, "rounding": "none", "source": "learned", "mapping_notes": "Learned from a correction on " + label + "."}
        links: dict[str, Any] = {}
        product_ids = od_link_ids(row, "product")
        if product_ids:
            links["product"] = product_ids[:1]
        if known:
            api.records.update(type_slug="od_customer_catalogue", record_id=known[0]["id"], record={"data": {"item_code": item_code, "source": "learned", "mapping_notes": mapping["mapping_notes"]}, "links": links} if links else {"data": {"item_code": item_code, "source": "learned", "mapping_notes": mapping["mapping_notes"]}})
        else:
            new_row: dict[str, Any] = {"title": (account_code + " / " + (customer_code or description))[:200], "data": mapping}
            if links:
                new_row["links"] = links
            api.records.create(type_slug="od_customer_catalogue", record=new_row)
        learned = True
        learned_count += 1
    for field, old, new in changes:
        data: dict[str, Any] = {"account_code": account_code, "field_changed": field, "old_value": old[:500], "new_value": new[:500], "reason": reason, "reason_note": reason_note[:2000], "corrected_on": od_now(), "learned": learned and field == "product"}
        if re.fullmatch(r"[0-9a-fA-F-]{36}", corrected_by):
            data["corrected_by"] = corrected_by
        api.records.create(type_slug="od_corrections", record={"title": (label + ": " + field.replace("_", " ") + " " + old + " -> " + new)[:200], "data": data, "links": {"order": [order_id], "order_line": [line_id]}})
        corrections += 1
    api.records.update(type_slug="od_order_lines", record_id=line_id, record={"data": {"corrected": True, "needs_review": False}})
for line_id, before in proposed.items():
    if line_id not in seen:
        api.records.create(type_slug="od_corrections", record={"title": (order_number + ": line " + show(before.get("line_number")) + " removed")[:200], "data": {"account_code": account_code, "field_changed": "line_removed", "old_value": (show(before.get("quantity")) + " " + od_text(before.get("unit")) + " " + od_text(before.get("item_code")))[:500], "new_value": "", "reason": reason, "reason_note": reason_note[:2000], "corrected_on": od_now(), "learned": False}, "links": {"order": [order_id]}})
        corrections += 1
